(() => {
 const byId=id=>document.getElementById(id);
 const launcher=byId('chatLauncher'),panel=byId('chatPanel'),scrim=byId('chatScrim'),feed=byId('chatMessages'),input=byId('chatInput'),send=byId('chatSend'),contextLabel=byId('chatContext');
 let started=false,ready=false,busy=false,controller=null,autoScroll=true,loadingHistory=false;
 function context(){return window.getSeasonContext()}
 function updateContext(){const c=context();contextLabel.textContent=c.term+' · '+c.phase;const buttons=byId('chatStarters');if(buttons){buttons.replaceChildren();[c.phase+'是什么意思？','一个节气为什么分三候？',c.term+'有什么习俗？'].forEach(question=>{const b=document.createElement('button');b.type='button';b.textContent=question;b.disabled=busy||loadingHistory;b.onclick=()=>ask(question);buttons.append(b)})}}
 function welcome(){feed.replaceChildren();const card=document.createElement('div');card.className='chat-welcome';card.id='chatWelcome';const title=document.createElement('h3');title.textContent='你好，我是拱拱。';const intro=document.createElement('p');intro.textContent='我喜欢慢慢看四季。节气、七十二候、相关的习俗，你想知道什么都可以问我，我用简单的话讲给你听。';const starters=document.createElement('div');starters.className='chat-starters';starters.id='chatStarters';card.append(title,intro,starters);feed.append(card);updateContext()}
 function scroll(force=false){if(force||autoScroll)feed.scrollTop=feed.scrollHeight}
 feed.addEventListener('scroll',()=>{autoScroll=feed.scrollHeight-feed.scrollTop-feed.clientHeight<70},{passive:true});
 function turn(role,text=''){byId('chatWelcome')?.classList.add('compact');const row=document.createElement('div');row.className='chat-turn '+role;const label=document.createElement('span');label.className='chat-turn-label';label.textContent=role==='user'?'你':'拱拱';const bubble=document.createElement('div');bubble.className='chat-bubble';bubble.textContent=text;row.append(label,bubble);feed.append(row);scroll();return {row,bubble}}
 function notice(message){byId('chatConnectionNotice')?.remove();const p=document.createElement('p');p.className='chat-notice';p.id='chatConnectionNotice';p.textContent=message;byId('chatWelcome')?.append(p)}
 function setBusy(value){busy=value;send.disabled=!value&&!input.value.trim();send.classList.toggle('stopping',value);send.textContent=value?'■':'↑';send.setAttribute('aria-label',value?'停止回答':'发送问题');input.setAttribute('aria-busy',String(value));byId('chatReset').disabled=value||loadingHistory;byId('chatStarters')?.querySelectorAll('button').forEach(b=>b.disabled=value||loadingHistory)}
 function autoSize(){input.style.height='40px';input.style.height=Math.min(110,input.scrollHeight)+'px';if(!busy)send.disabled=!input.value.trim()||loadingHistory}
 async function initialize(){loadingHistory=true;setBusy(false);try{const status=await fetch('/api/status',{cache:'no-store'});if(!status.ok)throw Error();const result=await status.json();ready=result.configured;if(!ready)notice('拱拱还在准备中，稍后就能和你聊节气了。');const history=await fetch('/api/chat/history',{cache:'no-store'});if(history.ok){const data=await history.json();if(Array.isArray(data.messages))for(const item of data.messages)if(['user','assistant'].includes(item.role)&&typeof item.content==='string')turn(item.role,item.content)} }catch{ready=false;notice('暂时连不上拱拱，你仍然可以浏览节气页面。')}finally{loadingHistory=false;setBusy(false);scroll(true)}}
 async function open(){panel.hidden=false;scrim.hidden=false;document.body.classList.add('chat-open');launcher.setAttribute('aria-expanded','true');updateContext();if(!started){started=true;welcome();await initialize()}input.focus({preventScroll:true})}
 function close(){panel.hidden=true;scrim.hidden=true;document.body.classList.remove('chat-open');launcher.setAttribute('aria-expanded','false');launcher.focus({preventScroll:true})}
 launcher.onclick=open;byId('chatClose').onclick=close;scrim.onclick=close;
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!panel.hidden&&!byId('drawer').open&&!window.Wardrobe?.isOpen()){e.preventDefault();close()}});
 document.addEventListener('seasonchange',updateContext);
 byId('chatReset').onclick=async()=>{if(busy||loadingHistory)return;try{const r=await fetch('/api/chat/reset',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});if(!r.ok)throw Error();welcome();input.value='';autoSize();input.focus()}catch{notice('没能开始新对话，请稍后再试。')}};
 async function ask(question){const text=question.trim();if(!text||busy||loadingHistory)return;if(text.length>1200){input.setCustomValidity('请把问题缩短到 1200 字以内。');input.reportValidity();return}input.setCustomValidity('');input.value='';autoSize();autoScroll=true;turn('user',text);const answer=turn('assistant');answer.bubble.classList.add('typing');answer.bubble.textContent='正在读你的问题';setBusy(true);controller=new AbortController();const timer=setTimeout(()=>controller?.abort('timeout'),75000);let output='',done=false,failed=false;
  function handle(event){if(event.type==='status'&&!output){answer.bubble.textContent=event.message;return}if(event.type==='delta'){output+=event.text;answer.bubble.classList.remove('typing');answer.bubble.textContent=output;scroll();return}if(event.type==='done'){done=true;return}if(event.type==='error'){failed=true;throw new Error(event.message||'这次没有连上，请稍后再试。')}}
  try{const c=context();const response=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:text,context:{termIndex:c.termIndex,houIndex:c.houIndex,date:c.date}}),signal:controller.signal});if(!response.ok){let error;try{error=await response.json()}catch{}throw new Error(error?.error||'暂时连不上拱拱，请稍后再试。')}if(!response.body)throw new Error('回答没有送达，请再试一次。');const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='';function block(value){for(const line of value.split('\n'))if(line.startsWith('data:'))handle(JSON.parse(line.slice(5).trim()))}try{while(true){const chunk=await reader.read();if(chunk.done)break;buffer+=decoder.decode(chunk.value,{stream:true}).replace(/\r\n/g,'\n');let idx;while((idx=buffer.indexOf('\n\n'))!==-1){block(buffer.slice(0,idx));buffer=buffer.slice(idx+2)}}buffer+=decoder.decode();if(buffer.trim())block(buffer)}finally{reader.releaseLock()}if(!done)throw new Error('回答中断了，请再试一次。');ready=true;byId('chatConnectionNotice')?.remove();
  }catch(error){answer.bubble.classList.remove('typing');if(controller.signal.aborted){const stopped=controller.signal.reason==='user';answer.bubble.textContent=output+(output?'\n\n':'')+(stopped?'已停止回答。':'等待有点久，请再试一次。')}else{failed=true;answer.row.classList.add('error');answer.bubble.textContent=output+(output?'\n\n':'')+(error.message||'连接暂时不稳定，请再试一次。')}if(failed||controller.signal.reason!=='user'){const retry=document.createElement('button');retry.className='chat-inline-action';retry.type='button';retry.textContent='再试一次';retry.onclick=()=>{if(!busy){retry.remove();ask(text)}};answer.row.append(retry)}}finally{clearTimeout(timer);controller=null;answer.bubble.classList.remove('typing');setBusy(false);scroll();if(!panel.hidden&&window.innerWidth>520)input.focus({preventScroll:true})}}
 byId('chatForm').addEventListener('submit',e=>{e.preventDefault();if(busy){controller?.abort('user');return}ask(input.value)});
 input.addEventListener('input',()=>{input.setCustomValidity('');autoSize()});input.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();if(!busy)ask(input.value)}});
 welcome();setBusy(false);
})();
